let pdfjs=null;
const documents=new Map(),positions=new Map();
async function load(url){pdfjs??=await import('/vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/vendor/pdf.worker.mjs';if(!documents.has(url))documents.set(url,pdfjs.getDocument({url,withCredentials:true,isEvalSupported:false}).promise.catch(e=>{documents.delete(url);throw e}));return documents.get(url)}
const mounted=new WeakSet();
export async function mountMaterialPDF(container,url){if(!container||mounted.has(container))return;mounted.add(container);const panel=container.closest('.material-pdf-panel');let current=positions.get(url)||1,renderId=0,task=null;try{const pdf=await load(url);current=Math.min(pdf.numPages,current);if(!container.isConnected)return;const counter=panel.querySelector('[data-pdf-counter]'),previous=panel.querySelector('[data-pdf-prev]'),next=panel.querySelector('[data-pdf-next]');
 async function draw(){positions.set(url,current);const id=++renderId;if(task){task.cancel();task=null}const page=await pdf.getPage(current);if(id!==renderId||!container.isConnected)return;const natural=page.getViewport({scale:1}),width=Math.max(220,container.clientWidth-32),scale=Math.min(2,width/natural.width),ratio=Math.min(2,window.devicePixelRatio||1),viewport=page.getViewport({scale:scale*ratio});const canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);canvas.style.width=Math.round(viewport.width/ratio)+'px';canvas.style.height=Math.round(viewport.height/ratio)+'px';canvas.setAttribute('role','img');canvas.setAttribute('aria-label','수업 자료 PDF '+current+'쪽');container.replaceChildren(canvas);counter.textContent=current+' / '+pdf.numPages+'쪽';previous.disabled=current===1;next.disabled=current===pdf.numPages;task=page.render({canvasContext:canvas.getContext('2d'),viewport});try{await task.promise}catch(e){if(e.name!=='RenderingCancelledException')throw e}}
 previous.addEventListener('click',()=>{if(current>1){current--;draw().catch(showError)}});next.addEventListener('click',()=>{if(current<pdf.numPages){current++;draw().catch(showError)}});
 function showError(){if(container.isConnected)container.textContent='PDF 표시 중 오류가 발생했습니다. 원본 PDF를 열어 확인하세요.'}
 await draw();
 }catch(e){if(container.isConnected)container.textContent='PDF를 불러오지 못했습니다. 원본 PDF 링크를 이용하세요.'}}
